"use server";
import { validate, type Errors, type Values } from "./validate";

export type State = { values: Values; errors: Errors; success: string | null };

export async function send(_prev: State, formData: FormData): Promise<State> {
  const get = (k: string) => String(formData.get(k) ?? "").trim();
  const values = { name: get("name"), email: get("email"), message: get("message") };
  const errors = validate(values);
  if (Object.keys(errors).length) return { values, errors, success: null };
  return {
    values: { name: "", email: "", message: "" },
    errors: {},
    success: `Thanks, ${values.name}! Your message has been sent.`,
  };
}
