"use client";
import { useActionState, useState } from "react";
import { send, type State } from "./actions";
import { validate, type Errors } from "./validate";

const initial: State = { values: { name: "", email: "", message: "" }, errors: {}, success: null };

export default function ContactForm() {
  const [state, action] = useActionState(send, initial);
  const [clientErrors, setClientErrors] = useState<Errors | null>(null);
  const errors = clientErrors ?? state.errors;
  const [seen, setSeen] = useState(state);
  if (seen !== state) {
    setSeen(state);
    setClientErrors(null);
  }

  return (
    <>
      {state.success && !clientErrors && <p role="status">{state.success}</p>}
      <form
        action={action}
        noValidate
        key={state.success ?? JSON.stringify(state.values)}
        onSubmit={(e) => {
          const fd = new FormData(e.currentTarget);
          const get = (k: string) => String(fd.get(k) ?? "").trim();
          const errs = validate({ name: get("name"), email: get("email"), message: get("message") });
          if (Object.keys(errs).length) {
            e.preventDefault();
            setClientErrors(errs);
          } else setClientErrors(null);
        }}
      >
        <div>
          <label htmlFor="name">Name</label>
          <input id="name" name="name" type="text" defaultValue={state.values.name} />
          {errors.name && <span>{errors.name}</span>}
        </div>
        <div>
          <label htmlFor="email">Email</label>
          <input id="email" name="email" type="email" defaultValue={state.values.email} />
          {errors.email && <span>{errors.email}</span>}
        </div>
        <div>
          <label htmlFor="message">Message</label>
          <textarea id="message" name="message" defaultValue={state.values.message} />
          {errors.message && <span>{errors.message}</span>}
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
